**Untested:** Concurrent drain lock, partial network failure leaves item in queue, `completed: false` path (delete).

```typescript
// mobile/tests/unit/syncQueue.test.ts
jest.mock('../../src/lib/supabase');
jest.mock('../../src/services/offline');
jest.mock('../../src/services/stats');

import { drainOfflineQueue } from '../../src/services/syncQueue';
import { getQueue, removeAction } from '../../src/services/offline';
import { supabase } from '../../src/lib/supabase';

test('returns 0 when queue empty', async () => {
  (getQueue as jest.Mock).mockResolvedValue([]);
  expect(await drainOfflineQueue()).toBe(0);
});

test('returns 0 when no authenticated user', async () => {
  (getQueue as jest.Mock).mockResolvedValue([{ id: '1', type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2026-05-23' }, ts: 0 }]);
  (supabase.auth.getUser as jest.Mock).mockResolvedValue({ data: { user: null } });
  expect(await drainOfflineQueue()).toBe(0);
});

test('syncs completed=true via upsert, removes from queue', async () => {
  const action = { id: 'a1', type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2026-05-23' }, ts: 0 };
  (getQueue as jest.Mock).mockResolvedValue([action]);
  (supabase.auth.getUser as jest.Mock).mockResolvedValue({ data: { user: { id: 'u1' } } });
  const upsertMock = jest.fn().mockResolvedValue({});
  (supabase.from as jest.Mock).mockReturnValue({ upsert: upsertMock });
  const result = await drainOfflineQueue();
  expect(result).toBe(1);
  expect(removeAction).toHaveBeenCalledWith('a1');
});

test('leaves action in queue on network failure', async () => {
  const action = { id: 'a1', type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2026-05-23' }, ts: 0 };
  (getQueue as jest.Mock).mockResolvedValue([action]);
  (supabase.auth.getUser as jest.Mock).mockResolvedValue({ data: { user: { id: 'u1' } } });
  (supabase.from as jest.Mock).mockReturnValue({ upsert: jest.fn().mockRejectedValue(new Error('net')) });
  const result = await drainOfflineQueue();
  expect(result).toBe(0);
  expect(removeAction).not.toHaveBeenCalled();
});

test('concurrent drains: second call returns 0 immediately', async () => {
  // Both calls start simultaneously — second should hit `if (draining) return 0`
  (getQueue as jest.Mock).mockImplementation(() => new Promise(r => setTimeout(() => r([]), 50)));
  const [r1, r2] = await Promise.all([drainOfflineQueue(), drainOfflineQueue()]);
  expect(r2).toBe(0);
});
```

