import { enqueueAction, getQueue, removeAction, clearQueue, getQueueLength } from '../../src/services/offline';

const mockStorage: Record<string, string> = {};
jest.mock('@react-native-async-storage/async-storage', () => ({
  getItem: (key: string) => Promise.resolve(mockStorage[key] ?? null),
  setItem: (key: string, val: string) => { mockStorage[key] = val; return Promise.resolve(); },
  removeItem: (key: string) => { delete mockStorage[key]; return Promise.resolve(); },
}));

beforeEach(() => { Object.keys(mockStorage).forEach(k => delete mockStorage[k]); });

test('enqueue adds action', async () => {
  await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2026-05-23' } });
  expect(await getQueueLength()).toBe(1);
});

test('enqueue deduplicates same habitId+date — last toggle wins', async () => {
  await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2026-05-23' } });
  await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: false, date: '2026-05-23' } });
  const q = await getQueue();
  expect(q).toHaveLength(1);
  expect(q[0].payload.completed).toBe(false); // last wins
});

test('removeAction removes by id', async () => {
  await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h2', completed: true, date: '2026-05-23' } });
  const [action] = await getQueue();
  await removeAction(action.id);
  expect(await getQueueLength()).toBe(0);
});

